# Visualize the grid to see patterns better
def visualize_grid(grid, color_map=None):
    """Visualize a grid with ASCII"""
    if color_map is None:
        color_map = {0: '.', '9': '#', '2': 'X'}

    lines = []
    for row in grid:
        lines.append(''.join(color_map.get(str(v), '?') for v in row))
    return '\n'.join(lines)

